function pageUI(){const list=$('pageList');list.replaceChildren();pages.forEach((p,i)=>{let src=thumbs.get(p.id);if(!src){src=composite(p,Math.min(220/p.w,130/p.h),false).toDataURL();thumbs.set(p.id,src);}const b=document.createElement('button');b.className='page-card'+(i===idx?' selected':'');b.setAttribute('aria-label','الصفحة '+ar(i+1));const im=document.createElement('img');im.src=src;im.alt='';const label=document.createElement('span');label.textContent=ar(i+1)+' · '+p.name;b.append(im,label);b.onclick=()=>switchPage(i);list.append(b);});$('pageLabel').textContent=page().name;$('pageNumber').textContent=ar(idx+1)+' / '+ar(pages.length);$('pageCount').textContent=ar(pages.length);$('prev').disabled=idx===0;$('next').disabled=idx===pages.length-1;}
