[['plain','سادة'],['lines','مسطّرة'],['grid','مربعات'],['dots','نقاط'],['double','سطران'],['narrow','تسطير ضيق'],['nine','٩ أسطر'],['isometric','أيزومتري'],['graph','بياني']].forEach(([p,t])=>{const b=document.createElement('button');b.dataset.pattern=p;b.innerHTML='<span class="pattern-preview '+p+'"></span>'+t;b.onclick=()=>{page().pattern=p;renderBackground();syncControls();thumbs.delete(page().id);pageUI();persist();};$('patterns').append(b);});
