function pos(e){const r=live.getBoundingClientRect();return{x:(e.clientX-r.left-pan.x)/(fit*zoom),y:(e.clientY-r.top-pan.y)/(fit*zoom),pressure:e.pointerType==='pen'?Math.max(.1,e.pressure):.5};}
