function textModal(p=viewCenter(),sticky=false){showModal('<h2>'+(sticky?'ملاحظة لاصقة':'أضف نصًا للدرس')+'</h2><textarea id="textInput" placeholder="اكتب جملة أو سؤالًا…" dir="auto"></textarea><label>حجم الخط</label><input id="textSize" type="number" min="16" max="150" value="42"><div class="actions"><button class="primary" id="insertText">إضافة إلى السبورة</button></div>');$('textInput').focus();$('insertText').onclick=()=>{const text=$('textInput').value.trim();if(!text)return;const fs=Math.min(150,Math.max(16,+$('textSize').value||42));const lines=text.split('\n');commit({type:sticky?'sticky':'text',text,fontSize:fs,x:p.x,y:p.y,w:Math.min(page().w*.9,Math.max(...lines.map(t=>t.length))*fs*.65),h:lines.length*fs*1.5,color,opacity:1,paper:'#f5e8ba'});closeModal();selectTool('select');};}
