async function importImage(file){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>20*1024*1024){toast('اختر صورة PNG أو JPG أو WebP أصغر من 20 ميجابايت.');return;}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const im=await loadImage(src),s=Math.min(1800/im.width,1800/im.height,1),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.width*s));c.height=Math.max(1,Math.round(im.height*s));c.getContext('2d').drawImage(im,0,0,c.width,c.height);const compressed=c.toDataURL('image/png');await loadImage(compressed);const f=Math.min(page().w*.7/c.width,page().h*.7/c.height,1);commit({type:'image',src:compressed,x:(page().w-c.width*f)/2,y:viewCenter().y,w:c.width*f,h:c.height*f,opacity:1});selectTool('select');selected=page().ops.length-1;renderSelection();toast('حُملت الصورة. اسحبها بأداة التحديد أو غيّر حجمها بزر + و−.');}catch{toast('تعذّر قراءة الصورة.');}}
$('imageBtn').onclick=()=>$('imageInput').click();$('imageInput').onchange=e=>{importImage(e.target.files[0]);e.target.value='';};document.addEventListener('paste',e=>{if(['INPUT','TEXTAREA'].includes(e.target.tagName)||$('modal').open)return;const image=[...(e.clipboardData?.items||[])].find(i=>i.type.startsWith('image/'));if(image){e.preventDefault();importImage(image.getAsFile());}});
async function importPDF(file){if(!file)return;if(file.size>60*1024*1024){toast('اختر ملف PDF أصغر من 60 ميجابايت.');return;}busy=true;let pdf,loading;try{showModal('<h2>تجهيز صفحات PDF</h2><p id="pdfProgress">قراءة الملف محليًا على جهازك…</p><progress id="pdfMeter" value="0" max="100"></progress><p>الملف لا يُرفع إلى أي خادم.</p>');const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;loading=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),cMapUrl:new URL('./vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/wasm/',import.meta.url).href,isEvalSupported:false});loading.onPassword=(update,reason)=>{const pass=prompt(reason===2?'كلمة المرور غير صحيحة. أدخلها مرة أخرى:':'هذا PDF محمي. أدخل كلمة مرور الملف:');if(pass===null){loading.destroy();}else update(pass);};pdf=await loading.promise;const limit=hasPro()?100:5;if(pdf.numPages>limit){closeModal();if(!hasPro()){showPro('استيراد أكثر من 5 صفحات PDF');}else toast('الملف أكبر من 100 صفحة. قسّمه إلى أجزاء قبل الاستيراد.');return;}if(pages.length+pdf.numPages>200){toast('لا يمكن أن يتجاوز الدرس 200 صفحة.');closeModal();return;}const added=[];for(let n=1;n<=pdf.numPages;n++){if($('pdfProgress'))$('pdfProgress').textContent='تجهيز الصفحة '+ar(n)+' من '+ar(pdf.numPages);if($('pdfMeter'))$('pdfMeter').value=(n-1)/pdf.numPages*100;const source=await pdf.getPage(n),v=source.getViewport({scale:1}),view=source.getViewport({scale:Math.min(2000/v.width,2000/v.height,3)});const canvas=document.createElement('canvas');canvas.width=Math.ceil(view.width);canvas.height=Math.ceil(view.height);await source.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;const src=canvas.toDataURL('image/png');await loadImage(src);added.push({...newPage(file.name.replace(/\.pdf$/i,'')+' · '+ar(n)),w:canvas.width,h:canvas.height,color:'#ffffff',pdf:src});source.cleanup();canvas.width=1;canvas.height=1;}
const start=pages.length;pages.push(...added);closeModal();busy=false;switchPage(start);toast('أُضيفت '+ar(added.length)+' صفحات. اكتب فوقها، والممحاة تمسح الشرح فقط.');}catch(err){closeModal();toast('تعذّر فتح PDF. تأكد من سلامة الملف وكلمة المرور إن وجدت.');console.error('PDF import failed',err?.message);}finally{busy=false;await loading?.destroy();}}
