async function loadProject(d){d=validateProject(d);clearTimeout(saveTimer);const pending=[];for(const p of d.pages){if(p.pdf)pending.push(loadImage(p.pdf));for(const o of p.ops)if(o.type==='image')pending.push(loadImage(o.src));}await Promise.all(pending);lessonId=typeof d.lessonId==='string'?d.lessonId:uid();pages=d.pages.map(p=>({...p,id:p.id||uid()}));title=typeof d.title==='string'?d.title.slice(0,80):'درس جديد';notes=typeof d.notes==='string'?d.notes:'';$('lessonName').value=title;history.clear();thumbs.clear();const i=Math.max(0,Math.min(pages.length-1,Math.trunc(d.idx)||0));busy=false;switchPage(i);}
