async function exportPDF(){busy=true;try{showModal('<h2>تصدير الدرس إلى PDF</h2><p id="exportProgress">تجهيز الصفحات…</p>');const pdf=await window.PDFLib.PDFDocument.create();pdf.setTitle(title);pdf.setAuthor(CONFIG.owner);for(let i=0;i<pages.length;i++){if($('exportProgress'))$('exportProgress').textContent='الصفحة '+ar(i+1)+' من '+ar(pages.length);const p=pages[i],c=composite(p);const png=await pdf.embedPng(await(await new Promise(resolve=>c.toBlob(resolve))).arrayBuffer());const out=pdf.addPage([p.w*.5,p.h*.5]);out.drawImage(png,{x:0,y:0,width:p.w*.5,height:p.h*.5});await new Promise(resolve=>setTimeout(resolve,0));}download(new Blob([await pdf.save()],{type:'application/pdf'}),titleSafe()+'.pdf');closeModal();toast('تم تجهيز PDF بكل الصفحات والشرح.');}catch{toast('تعذّر التصدير؛ جرّب درسًا أصغر أو احفظه كملف درس.');closeModal();}finally{busy=false;}}
