$('saveBtn').onclick=saveModal;$('openBtn').onclick=()=>$('projectInput').click();$('projectInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>200*1024*1024)throw Error();const d=validateProject(JSON.parse(await f.text()));if(pages.some(p=>p.ops.length||p.pdf)&&!confirm('فتح الدرس سيستبدل الدرس الحالي. هل حفظت نسختك وتريد المتابعة؟'))return;if(hasLessonContent(project())||dirty)await flushProject(true);busy=true;await loadProject(d);toast('تم فتح الدرس.');}catch{toast('تعذّر فتح الملف. استخدم ملف درس صالحًا من سبّورتي.');}finally{busy=false;e.target.value='';}};
function hasPro(){return isLicenseActive(license);}
function updateEdition(){const active=hasPro(),period=licensePeriod(license);$('edition').textContent=active?(period.kind==='perpetual'?'Pro دائم':'Pro شهري'):license?'اشتراك منتهٍ':'مجاني';$('proBtn').textContent=active?'✦ ترخيص Pro':'✦ سبّورتي Pro';}
