function subscriptionDetails(){if(!license)return '';const p=licensePeriod(license);if(p.kind==='perpetual')return '<p class="notice">ترخيصك الدائم السابق محفوظ، ولا يحتاج إلى اشتراك شهري.</p>';return '<p class="notice">'+(hasPro()?'اشتراكك مفعّل حتى: ':'انتهى الاشتراك في: ')+escape(new Date(p.end).toLocaleString('ar-EG'))+' — دروسك محفوظة ويمكنك فتحها وحفظها مجانًا.</p>';}
