$('proBtn').onclick=()=>showPro();$('licenseInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error();const text=await f.text();const verified=await verifyLicense(text,CONFIG.publicKey);await licenseStorage.save(text);license=verified;enforceSubscription();showPro();toast(hasPro()?'تم تفعيل Pro بنجاح.':'الترخيص منتهٍ أو لم تبدأ مدته بعد؛ افتح ملف تجديد سارٍ.');}catch{toast('الترخيص غير صالح لهذه النسخة أو تعذّر حفظه.');}finally{e.target.value='';}};
