let timerSeconds=300,timerRemaining=300,timerEnd=0,timerId=null;function timerRender(){const n=timerId?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):timerRemaining;$('timerDisplay').textContent=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');if(timerId&&n===0){clearInterval(timerId);timerId=null;timerRemaining=0;$('timerToggle').textContent='ابدأ';toast('انتهى وقت النشاط. أحسنتم!');celebrate();}}
