function celebrate(){const box=$('celebration');box.replaceChildren();for(let i=0;i<28;i++){const s=document.createElement('span');s.textContent=['✦','★','✧','●'][i%4];s.style.left=Math.random()*100+'%';s.style.animationDelay=Math.random()*.6+'s';s.style.color=['#bca26a','#88a77b','#81a9b4','#c99a8a'][i%4];box.append(s);}setTimeout(()=>box.replaceChildren(),3400);}$('confettiBtn').onclick=celebrate;
