let names='أحمد\nعمر\nمريم\nسارة';$('wheelBtn').onclick=()=>requirePro('الاختيار العشوائي',()=>{showModal('<h2>لمن الدور هذه المرة؟</h2><p>اكتب اسمًا أو فكرة في كل سطر.</p><textarea id="names">'+escape(names)+'</textarea><div class="winner" id="winner">؟</div><button id="pickName" class="primary wide">اختيار عشوائي</button>');$('pickName').onclick=()=>{names=$('names').value;const list=names.split('\n').map(s=>s.trim()).filter(Boolean);if(!list.length)return;const a=new Uint32Array(1);crypto.getRandomValues(a);$('winner').textContent=list[a[0]%list.length];};});
$('notesBtn').onclick=()=>requirePro('ملاحظات المعلم',()=>{showModal('<h2>ملاحظات المعلم</h2><p>تُحفظ مع الدرس. أغلق هذه النافذة قبل مشاركة الشاشة إذا أردت إخفاءها عن الطلاب.</p><textarea id="teacherNotes" style="min-height:230px">'+escape(notes)+'</textarea><div class="actions"><button id="saveNotes" class="primary">حفظ الملاحظات</button></div>');$('saveNotes').onclick=()=>{notes=$('teacherNotes').value;persist();closeModal();};});
$('quizBtn').onclick=()=>requirePro('الأسئلة التفاعلية',()=>{showModal('<h2>سؤال سريع لطلابك</h2><label>السؤال</label><input id="question" type="text" value="ما نوع كلمة «يكتب»؟"><label>الاختيارات — اختيار في كل سطر</label><textarea id="answers">اسم\nفعل\nحرف</textarea><label>رقم الإجابة الصحيحة</label><input id="correctAnswer" type="number" value="2" min="1" max="8"><div class="actions"><button id="showQuestion" class="primary">عرض السؤال</button></div>');$('showQuestion').onclick=()=>{const question=$('question').value,choices=$('answers').value.split('\n').map(s=>s.trim()).filter(Boolean).slice(0,8),correct=+$('correctAnswer').value-1;if(!question.trim()||choices.length<2||correct<0||correct>=choices.length){toast('أدخل سؤالًا واختيارين على الأقل ورقم إجابة صحيحًا.');return;}showModal('<div class="eyebrow">فكّر، ثم اختر</div><h2>'+escape(question)+'</h2>'+choices.map((s,i)=>'<button class="choice" data-answer="'+i+'">'+escape(s)+'</button>').join('')+'<p id="feedback"></p>');document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const good=+b.dataset.answer===correct;b.classList.add(good?'correct':'wrong');$('feedback').textContent=good?'أحسنت! إجابة صحيحة.':'محاولة جيدة. فكّر مرة أخرى.';if(good)celebrate();});};});
initFloatingCamera($('cameraFloat'),$('cameraDragHandle'));
const cameraBackground=initCameraBackground({video:$('cameraVideo'),canvas:$('cameraProcessed'),controls:$('cameraBackgroundControls'),status:$('cameraBackgroundStatus'),onError:toast});
let cameraStream=null;$('cameraBtn').onclick=()=>requirePro('نافذة الكاميرا',async()=>{try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{width:640,height:480},audio:false});if(!hasPro()){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;return;}await cameraBackground.attach(cameraStream);$('cameraFloat').hidden=false;}catch{toast('تعذّر فتح الكاميرا. تحقق من الإذن ومن عدم استخدامها بواسطة برنامج آخر.');}});$('cameraClose').onclick=()=>{cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;cameraBackground.detach();$('cameraFloat').hidden=true;};
function openVideoLesson(lesson,targetPage){showModal('<div id="videoLesson"></div>');$('modal').classList.add('video-lesson-dialog');const cameraParent=$('cameraFloat').parentElement,root=$('videoLesson');const dispose=mountVideoLesson({root,lesson,onChange:()=>{thumbs.delete(targetPage.id);persist();},toast});root.append($('cameraFloat'));videoLessonDispose=()=>{cameraParent.append($('cameraFloat'));dispose();};}
$('youtubeBtn').onclick=()=>{
 const target=page();showModal('<h2>شرح على فيديو YouTube</h2><p>أضف فيديو ثم بدّل بين تشغيله والكتابة فوقه. الشرح يُحفظ مع صفحة الدرس.</p><label>رابط الفيديو<input id="youtubeUrl" type="url" placeholder="https://www.youtube.com/watch?v=…"></label><button id="insertVideo" class="primary">فتح الفيديو للشرح</button><div id="savedVideos"></div>');
 for(const [i,lesson] of (target.videos||[]).entries()){const b=document.createElement('button');b.textContent='فتح الفيديو المحفوظ '+ar(i+1);b.onclick=()=>openVideoLesson(lesson,target);$('savedVideos').append(b);}
 $('insertVideo').onclick=()=>{try{const id=youtubeId($('youtubeUrl').value);target.videos??=[];let lesson=target.videos.find(v=>v.id===id);if(!lesson){if(target.videos.length>=10)throw Error('الحد الأقصى 10 فيديوهات لكل صفحة. استخدم صفحة جديدة.');lesson={id,ops:[]};target.videos.push(lesson);persist();}openVideoLesson(lesson,target);}catch(error){toast(error.message);}};
};
let recorder=null,recordInterval,recordStart=0,recordingStarting=false,recordingAbort=null;
function recordCleanup(){clearInterval(recordInterval);$('recordStatus').hidden=true;recordingStarting=false;recorder=null;recordingAbort=null;}
async function startRecording(){
 if(!window.MediaRecorder||!navigator.mediaDevices?.getDisplayMedia){showModal('<h2>تسجيل النافذة كاملة</h2><p>هذا المتصفح لا يوفّر تسجيل الشاشة للموقع. افتح السبورة على الكمبيوتر في Chrome أو Edge حديث، ثم اضغط التسجيل. لا تحتاج برنامج تسجيل خارجي.</p>');return;}
 if(recordingStarting||recorder?.state==='recording'){toast('التسجيل يعمل أو يجري تجهيزه.');return;}
 showModal('<h2>تسجيل النافذة والكاميرا والصوت</h2><p>يسجّل كل ما يظهر في تبويب السبورة أو نافذتها: الكتابة وPDF والكاميرا والقوائم والفيديو الظاهر.</p><ol><li>اضغط بدء، ثم اختر <b>تبويب السبورة الحالي</b> أو نافذتها واضغط مشاركة.</li><li>اسمح بالميكروفون والكاميرا عند الطلب. يمكنك تغيير خلفية الكاميرا من قائمتها أثناء التسجيل.</li><li>لصوت الفيديو، فعّل «مشاركة صوت التبويب» في اختيار المتصفح. استخدام سماعات يقلل صدى الميكروفون.</li></ol><label><input type="checkbox" id="recordMic" checked> تسجيل الميكروفون</label><label><input type="checkbox" id="recordCamera" checked> إظهار الكاميرا داخل نافذة السبورة</label><label><input type="checkbox" id="recordSharedAudio" checked> طلب تسجيل صوت التبويب أو النافذة</label><p class="notice">اختر نافذة السبورة التي تحتوي على الكاميرا لتظهر في التسجيل. أذونات الالتقاط مطلوبة في كل مرة. قد لا يدعم الهاتف هذه الخاصية، وصوت النافذة يتوقف على المتصفح والنظام. يُحفظ الفيديو على جهازك عند الإيقاف.</p><button id="beginRecord" class="primary">اختيار النافذة وبدء التسجيل</button>');
 $('beginRecord').onclick=async()=>{
  if(recordingStarting||recorder?.state==='recording')return;if(!hasPro()){showPro('تسجيل النافذة');return;}
  const microphone=$('recordMic').checked,camera=$('recordCamera').checked,sharedAudio=$('recordSharedAudio').checked;
  $('beginRecord').disabled=true;recordingStarting=true;recordingAbort=new AbortController();const abort=recordingAbort;
  try{
   const session=await createWindowRecording({microphone,camera,sharedAudio,existingCamera:cameraStream,signal:abort.signal,
    onCamera:async stream=>{cameraStream=stream;await cameraBackground.attach(stream);$('cameraFloat').hidden=false;},
    onCameraReleased:()=>{cameraStream=null;cameraBackground.detach();$('cameraFloat').hidden=true;},
    onStarted:()=>{if(!hasPro()){abort.abort();return;}closeModal();recordingStarting=false;recordStart=Date.now();$('recordStatus').hidden=false;$('recordTime').textContent='00:00';recordInterval=setInterval(()=>{const t=Math.floor((Date.now()-recordStart)/1000);$('recordTime').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');},500);},
    onFinished:(blob,mime)=>{recordCleanup();if(blob.size){download(blob,titleSafe()+(mime.includes('mp4')?'.mp4':'.webm'));toast('تم تجهيز تسجيل النافذة للتنزيل.');}else toast('لم ينتج ملف فيديو؛ أعد المحاولة.');},onWarning:toast,onError:()=>toast('حدث خطأ أثناء التسجيل. جارٍ تجهيز الجزء المسجل إن وجد.')
   });if(session.state==='recording')recorder=session;
  }catch(error){recordCleanup();if($('beginRecord'))$('beginRecord').disabled=false;toast(error.name==='NotAllowedError'?'لم يبدأ التسجيل: لم تُمنح أذونات مشاركة النافذة أو الميكروفون أو الكاميرا.':error.name==='AbortError'?'أُلغي التسجيل.':error.message||'تعذّر بدء التسجيل.');}
 };
}
$('recordBtn').onclick=()=>requirePro('تسجيل النافذة والكاميرا والصوت',startRecording);$('stopRecord').onclick=()=>recorder?.stop();
$('helpBtn').onclick=()=>showModal('<div class="eyebrow">دليل سريع</div><h2>كل ما تحتاجه لبدء درس جميل</h2><ol><li>اختر القلم واللون والسُّمك، واكتب بالماوس أو القلم اللمسي.</li><li>غيّر لون السبورة والتسطير من الجانب. أدخل PDF من «شرح على ملف PDF».</li><li>استخدم أداة التحديد لتحريك الصورة أو النص أو الرسم، ثم + و− لتغيير حجمه.</li><li>كبّر بأزرار الأسفل أو Ctrl مع عجلة الماوس، وحرّك المساحة بأداة اليد.</li><li>شارك نافذة السبورة في Zoom أو Meet. التسجيل الخارجي يلتقط الشاشة والميكروفون حسب إعداداته.</li><li>نزّل ملف الدرس لتكمل الشرح لاحقًا أو على جهاز آخر.</li></ol><p class="notice">الاختصارات: P قلم · E ممحاة · V تحديد · H تحريك · T نص · K ليزر · Ctrl+Z تراجع · Ctrl+Y إعادة · Ctrl+S حفظ · Home ملاءمة الصفحة.</p><p>مشاركة الشاشة تحتاج برنامج الاجتماعات. الكتابة المشتركة المتزامنة بين أجهزة الطلاب غير متاحة في هذا الإصدار.</p>');
$('aboutBtn').onclick=()=>showModal('<div class="eyebrow">SABOURATI · '+CONFIG.appVersion+'</div><h2>صُمّمت للشرح، باسمك</h2><p>© 2026 أحمد أشرف عبد العليم. جميع الحقوق محفوظة في الاسم والتصميم والكود الأصلي لسبّورتي. لا يشمل ذلك مكتبات الطرف الثالث الخاضعة لتراخيصها.</p><p>البرنامج مجاني بأدوات أساسية، واشتراك Pro بسعر 100 جنيه شهريًا، مع الحفاظ على التراخيص الدائمة السابقة. دروسك والترخيص محليان على جهازك. لا يوجد رفع إيصالات أو خصم تلقائي في هذه النسخة. قد يتصل YouTube بخوادمه عندما تختار عرض فيديو.</p><p>يتضمن البرنامج PDF.js وpdf-lib وJSZip. تراخيصها مرفقة مع حزم التطبيق.</p><p class="notice">إشعار الحقوق هنا لا يعني تسجيل علامة تجارية أو شهادة ملكية رسمية.</p>');
let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
$('downloadBtn').onclick=()=>{const url=location.origin+location.pathname.replace(/index\.html$/,'');showModal('<h2>شارك سبّورتي برابط مباشر</h2><p>تعمل في المتصفح على Windows وMac دون تحميل. الأدوات الأساسية مجانية، وPro بسعر 100 جنيه شهريًا.</p><input id="shareUrl" readonly dir="ltr" aria-label="رابط السبورة" value="'+url+'"><button id="copyShare" class="primary">نسخ الرابط</button><p id="copyResult" role="status"></p>');$('copyShare').onclick=async()=>{try{await navigator.clipboard.writeText(url);$('copyResult').textContent='تم نسخ الرابط.';}catch{$('shareUrl').select();$('copyResult').textContent='انسخ الرابط المحدد.';}};};
document.addEventListener('keydown',e=>{if(e.defaultPrevented||isTextEditing(e.target)||$('modal').open||busy)return;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();}else if((e.ctrlKey||e.metaKey)&&key==='y'){e.preventDefault();$('redo').click();}else if((e.ctrlKey||e.metaKey)&&key==='s'){e.preventDefault();saveProject();}else if(e.key==='Delete'||e.key==='Backspace'){if(selected>=0){e.preventDefault();$('deleteObject').click();}}else if(e.key==='Home'){resetView();}else if(e.key==='Escape'){if(document.body.classList.contains('focus'))exitFocus();$('spotlight').hidden=true;$('curtain').hidden=true;selectTool('pen');}else if(!e.ctrlKey&&!e.metaKey){const map={p:'pen',e:'eraser',v:'select',h:'hand',t:'text',k:'laser',a:'arrow',r:'rect',c:'ellipse'};if(map[key])selectTool(map[key]);}});
window.addEventListener('beforeunload',e=>{if(dirty||recordingStarting||recorder?.state==='recording'){e.preventDefault();e.returnValue='';}});
$('modal').addEventListener('close',()=>{disposeVideoLesson();const frame=$('modalContent').querySelector('iframe');if(frame)frame.remove();});
async function boot(){
 switchPage(0);selectTool('pen');let resumed=false;
 try{const saved=await read('project');const legacy=!saved&&localStorage.getItem('sabourati-v1');const previous=saved||(legacy?JSON.parse(legacy):null);if(previous&&hasLessonContent(previous)){const valid=validateProject(previous);if(valid.lessonId)await lessonStorage.archive(valid);else await lessonStorage.save(valid);}
  const resumeId=takeUpdateLesson(sessionStorage);if(resumeId){const lesson=await lessonStorage.open(resumeId);if(lesson){await loadProject(lesson);resumed=true;}}
 }catch{toast('تعذّرت قراءة بعض الدروس السابقة. لم تُحذف؛ جرّب «دروسي المحفوظة» أو افتح نسخة محفوظة.');}
 try{const restored=await licenseStorage.restore();if(restored){license=restored.license;wasPro=hasPro();updateEdition();}}catch{toast('تعذّرت استعادة الترخيص. افتح ملف الترخيص المحفوظ.');}
 if(!resumed&&night){page().color='#12213b';chooseColor('#e2ecff');}
 for(const p of pages){if(['#172b32','#243e34'].includes(p.color))p.color='#12213b';if(p.color==='#e9f0e2')p.color='#e5ecfa';}renderBackground();syncControls();restoring=false;updateRenewalReminder();
 initAppUpdates({version:CONFIG.appVersion,canApply:()=>canChangeLesson()&&!$('modal').open&&!document.body.classList.contains('focus'),save:async()=>{await flushProject(true);if(dirty)throw Error('الدرس ما زال يتغير');},resume:()=>rememberUpdateLesson(sessionStorage,lessonId),notice:(message,apply)=>{const n=$('updateNotice');$('updateText').textContent=message;n.hidden=false;$('applyUpdate').onclick=apply;}});
}

initExtras({penStyle:()=>({color,size,opacity}),$,showModal,closeModal,escape,toast,selectTool,commit,viewCenter,page,images,background,ink,live,requirePro,celebrate,pointFromClient:pos,setBackground:(src,w,h)=>{page().pdf=src;page().w=w;page().h=h;thumbs.delete(page().id);switchPage(idx);}});
const paymentDialog=initCommerce({CONFIG,showModal,escape,$,toast,verifyLicense,store:(_key,text)=>licenseStorage.save(text),setLicense:l=>{license=l;updateEdition();}});
let night=false;try{night=localStorage.getItem('sabourati-theme')==='dark';}catch{}
function themeUI(){document.documentElement.dataset.theme=night?'dark':'light';$('themeBtn').textContent=night?'☀ نهاري':'☾ ليلي';$('themeBtn').setAttribute('aria-pressed',String(night));}
$('themeBtn').onclick=()=>{night=!night;themeUI();try{localStorage.setItem('sabourati-theme',night?'dark':'light');}catch{}if(!page().pdf){changeBackground(night?'#12213b':'#fcfdff');chooseColor(night?'#e2ecff':'#263e67');}};themeUI();
boot();
